#' Table of synthetic outcome significance levels.
#' 
#'@description
#' `synth_table()` Makes a summary table of estimated and synthetic outcome p values from output generated by 
#' [synth()] or [iv_synth()], with every inference method in one table.
#' 
#' @param syn An object containing simulation results created by [synth()] or [iv_synth()].
#' @param caption An optional caption for the table.
#'
#' @return Generates a tinytable object. This gives the regression and synthetic outcome p values with HC
#'  inference, with BCH and IM inference as the number of clusters increases, and with SCPC inference as
#'  the bound `avc` increases (when `avc` was given), as in [placebo_table()]. For [iv_synth()] results
#'  the table has a block of 2SLS rows followed by a block of Anderson-Rubin rows.
#'  The regression confidence interval and its width are also reported. The next part of the table gives
#'  the z-score of a Moran test, using 5 nearest neighbours, the R2 of a regression of the outcome on a
#'  quadratic in longitude and latitude, and the effective range and structure of this regression's residuals.
#' @export
#'
#' @examples
#' library(spatInfer)
#' data(opportunity)
#' # Use 100 observations and 100 simulations to speed things up.
#' set.seed(123)
#' opportunity=opportunity |> dplyr::slice_sample(n=100)
#' # Use the number of splines and PCs indicated by [optimal_basis()] and turn off parallel processing.
#' synt=synth(mobility~single_mothers+short_commute+gini+dropout_rate+social_cap+dropout_na,
#' opportunity,
#' splines=6,
#' pc_num=15,
#' nSim=100,
#' Parallel=FALSE,
#' max_clus = 7,
#' avc=c(0.02,0.04)
#' )
#' synth_table(synt, caption="Synthetic outcomes significance levels for single mothers variable.")


synth_table=function(syn, caption=""){
sim_table(syn,"synth",caption)
}
